# -*- coding: utf-8 -*-
"""Два авторских набора по статистике для 11 класса; примеры — учебные, не исторические данные."""
from schema import cat, q

def make(cid, names, fact, rows):
    # Каждая тема начинает с релевантной заметки; остальные факты чередуются,
    # чтобы после каждого ответа не повторялась одна и та же история.
    pool = [fact] + [f for f in (SNOW, NIGHTINGALE, GALTON, PEARSON, BAYES) if f != fact]
    return cat(cid, *names, [q(*question, *answer, *pool[i % len(pool)]) for i, (question, answer) in enumerate(rows)])

SNOW = ('В 1854 году Джон Сноу нанёс случаи холеры на карту Лондона, изучая связь вспышки с водяной колонкой.', '1854 жылы Джон Сноу тырысқақ жағдайларын Лондон картасына түсіріп, індет пен су сорғысының байланысын зерттеді.', 'In 1854 John Snow mapped London cholera cases while studying the outbreak’s link to a water pump.')
